window.RP_SESSION={"id":"S-2a3ecb0e2470","messages":[{"id":"RP-0178602","time":"2026-06-30T12:19:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 내가 어렸을 때 말야. \"","characters":[]},{"id":"RP-0178603","time":"2026-06-30T12:19:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 남자애 두명을 좋아한 적이 있어. \"","characters":[]},{"id":"RP-0178604","time":"2026-06-30T12:20:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"오","characters":["P-3ea4affc20fd"]},{"id":"RP-0178605","time":"2026-06-30T12:20:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 9살 때랑 13살 때, 사실 사랑이라기보단 그냥 친구가 되고 싶은 거였는데. \"","characters":[]},{"id":"RP-0178606","time":"2026-06-30T12:21:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 둘이 똑같이, 피부도 하얗고... 뭐랄까. 아는 것도 많고. 똑부러지는... \"","characters":[]},{"id":"RP-0178607","time":"2026-06-30T12:21:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 생각해보니 성씨도 같았네. \"","characters":[]},{"id":"RP-0178608","time":"2026-06-30T12:28:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"성씨도 같을 수가 있나?\"\n\n 아니 뭐 가능?은 하겠지만?","characters":["P-3ea4affc20fd"]},{"id":"RP-0178609","time":"2026-06-30T12:29:00+09:00","room":"RP","name":"장면 밖 논평","profile":"존","identity":"reviewed","type":"dialogue","body":"(사실 형제였다던가?","characters":["P-e1760f10b030"]},{"id":"RP-0178610","time":"2026-06-30T12:30:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"*그치만 동갑인걸","characters":["P-3ea4affc20fd"]},{"id":"RP-0178611","time":"2026-06-30T12:31:00+09:00","room":"RP","name":"장면 밖 논평","profile":"존","identity":"reviewed","type":"dialogue","body":"(쌍둥이일수도 있죠","characters":["P-e1760f10b030"]},{"id":"RP-0178612","time":"2026-06-30T12:31:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 응. 성씨도 같았어. \"","characters":[]},{"id":"RP-0178613","time":"2026-06-30T12:32:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"거 희안하네.\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0178614","time":"2026-06-30T12:32:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"친척인감?\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0178615","time":"2026-06-30T12:33:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 13살 때 애는 동네 아주머니 부탁으로 마굿간 앞에 뭘 가지러 갔다가 그날 처음 만난 애였는데, \"","characters":[]},{"id":"RP-0178616","time":"2026-06-30T12:33:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 마굿간 문이 안 열려 있어서 그 앞에서 떠들었었지. \"","characters":[]},{"id":"RP-0178617","time":"2026-06-30T12:36:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 몰라? 그냥 둘 다 같았어. \"","characters":[]},{"id":"RP-0178618","time":"2026-06-30T12:36:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그렇구만, 그래서 어떻게 됐는데?\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0178619","time":"2026-06-30T12:39:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그냥 심부름 했지. \"","characters":[]},{"id":"RP-0178620","time":"2026-06-30T12:39:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 걔는 다른 일을 하러 갔거든. \"","characters":[]},{"id":"RP-0178621","time":"2026-06-30T12:39:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"허무하네~.\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0178622","time":"2026-06-30T12:44:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"뭐, 내 첫사랑 이야기 하기도 좀 그렇고.\"\n\n 전쟁때 죽었거든.","characters":["P-3ea4affc20fd"]},{"id":"RP-0178623","time":"2026-06-30T12:46:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 사이먼 씨도요? 제 첫사랑도 좀···. 마지막에 꽤나 더럽게 끝났었어요. ”\n\n내가 죽였거든","characters":["P-b6d81d634c6e"]},{"id":"RP-0178624","time":"2026-06-30T12:48:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"뭐, 첫사랑은 이뤄지지 않는 법이라고 하잖나.\"\n\n 차 따라주기.","characters":["P-3ea4affc20fd"]},{"id":"RP-0178625","time":"2026-06-30T12:49:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 사실 첫사랑만큼 몽글몽글한 것도 없긴 하잖아요. ”\n\n따라준 차 빤히 바라보다가.\n\n“ 가끔 그림들을 볼 때마다 생각 나는, 그런 몽글몽글함이요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0178626","time":"2026-06-30T12:51:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그렇지. 뭔가 따뜻한 느낌도 나고\"\n\n 이 쪽은 남겨진 거 하나없지만. 애초에 난 라운데라님 거니까 큰미련은 없다.\n\n \"음. 젊을 때 생각나는구만.\"","characters":["P-3ea4affc20fd"]},{"id":"RP-0178627","time":"2026-06-30T12:53:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 네 첫사랑은 누구였는데? \"","characters":[]},{"id":"RP-0178628","time":"2026-06-30T12:54:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 저요? 저는···. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0178629","time":"2026-06-30T12:54:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 음······. 션 나이 또래인 분이었어요. 제 첫 스승이기도 했고. “\n\n” 제일 의지할 수 있는 분이었어요. “","characters":["P-b6d81d634c6e"]},{"id":"RP-0178630","time":"2026-06-30T12:55:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 검술도 배우다가, 훈련도 하다가, 음···. 그냥 풋풋한 연애였어요. 섬이 제 고향이었으니까. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0178631","time":"2026-06-30T12:55:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"저 때도 엄청난 연상 취향이엇구나...","characters":["P-3ea4affc20fd"]},{"id":"RP-0178632","time":"2026-06-30T12:56:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 그건 기억이 나요. 언덕에 같이 누워서는···. 구름 가지고 농담했을 때요. 저건 우리 미래 집처럼 생겼네 아니네···. 뭐 그런 거요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0178633","time":"2026-06-30T12:57:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 음. 근데 그닥···. 좋은 사람은 아니었어요. ”\n\n“ 왜, 눈 앞에 보라색 꽃잎을 두고 햇빛을 바라보면 시야가 약간 보랏빛으로 변하잖아요? 그런 것처럼 제 기억에도 색이 남아있었나봐요. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-0178634","time":"2026-06-30T12:57:00+09:00","room":"RP","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 생각해보니 처음부터 끝까지 다 부러진 칼보다도 못했죠. “","characters":["P-b6d81d634c6e"]},{"id":"RP-0178635","time":"2026-06-30T13:01:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그래도 떠올릴 때 즐거웠으면 좋겠구나.\"\n\n 우유 홀짝.","characters":["P-3ea4affc20fd"]},{"id":"RP-0178636","time":"2026-06-30T13:17:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 어쩌면 좋은 사람이었을지 몰라. \"","characters":[]},{"id":"RP-0178637","time":"2026-06-30T13:17:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 내가 만날 수 있는 최고의 사람이었을지도 모르구. \"","characters":[]},{"id":"RP-0178638","time":"2026-06-30T13:18:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 지금은 틀리지만, 그때는 맞았으니까... \"","characters":[]},{"id":"RP-0178639","time":"2026-06-30T13:19:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 생각해보니 난 한 번도 제대로 된 연애를 해보지 못한 것 같네. \"","characters":[]},{"id":"RP-0178640","time":"2026-06-30T13:20:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 뜨겁지만 잠깐이었고. 그럴싸해보여도 허물이었고. \"","characters":[]},{"id":"RP-0178641","time":"2026-06-30T13:20:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 나는 내가 좋아하는 사람이 아니라. 남이 좋아하는 사람이 내 것인게 좋았던 것 같아. \"","characters":[]},{"id":"RP-0178642","time":"2026-06-30T13:25:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 그래서 그렇게 자주 싸웠나? \"","characters":[]},{"id":"RP-0178643","time":"2026-06-30T13:25:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 싸웠다기보단 일방적인 내 투정에 가까웠지만. \"","characters":[]},{"id":"RP-0178644","time":"2026-06-30T13:25:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" ㅎ. \"","characters":[]},{"id":"RP-0178645","time":"2026-06-30T13:25:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 저런","characters":["P-3ea4affc20fd"]},{"id":"RP-0178646","time":"2026-06-30T13:28:00+09:00","room":"RP","name":"사이먼","profile":"올리브","identity":"reviewed","type":"dialogue","body":"  \"나는 연애 경험이 없어서 잘 모르겠군.\"\n\n 그렇게 됐다.","characters":["P-3ea4affc20fd"]},{"id":"RP-0178647","time":"2026-06-30T15:36:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 무튼. 사실 아직도 잘 모르겠어. 돈 버는 건 익숙한데, 사랑에는 어색해. \"","characters":[]},{"id":"RP-0178648","time":"2026-06-30T15:37:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 못난이 가고 멋쟁이 온다던데, 그 못난이가 내 최고의 멋쟁이였을지도 모르고. \"","characters":[]},{"id":"RP-0178649","time":"2026-06-30T15:38:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 못난인줄 알았는데 남에겐 멋쟁이였을지도 모르고. \"","characters":[]},{"id":"RP-0178650","time":"2026-06-30T15:39:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 에휴, 다 늙어서 이런 생각 해봤자 뭐해~! \"","characters":[]},{"id":"RP-0178651","time":"2026-06-30T15:40:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"\" 차라리 아무것도 모를 때 적당한 못난이랑 적당하게 살았다면 좀 달라졌을까? \"","characters":[]},{"id":"RP-0178652","time":"2026-06-30T16:03:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"어렸을 때 가장 큰 걱정은 생일에 가지고 싶었던 예쁜 민트색 구두를 받게 될지, 아니면 아침에 쿠키를 먹을 수 있는지와 같은 것이었다.\n\n어른이라는 건 완전히 과대평가받고 있다.\n섹시한 구두, 연인과의 환상적인 성관계, 잔소리하는 부모가 없다는 사실에 속아 넘어가지 말 지어다. \n\n인생은 파란만장 섹스 오브 시티 같은 게 아니니까.\n\n성인기는 곧 책임감을 뜻한다.\n책임감은 정말 최악이다. 정말 정말로.\n\n어른은 직업이 있어야 하고. 일도 해야 하고.\n생계를 꾸려 나가고, 거지 같은 집세도 내야 한다.\n\n왠지, 예쁜 민트색 구두와 쿠키가 정말 정말 끌리는 순간이다.\n\n그리고, 지금 이 순간 날 잔소리해 줄\n그립고 말게 된 부모님도.","characters":[]},{"id":"RP-0178653","time":"2026-06-30T16:03:00+09:00","room":"RP","name":"인물 미확정 — 첫사랑을 이야기한 인물","profile":"Seon \"South Foot\"","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-0178654","time":"2026-06-30T16:03:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
